  assert.deepEqual(
    matchServerWorktrees(worktrees, repos, { displayName: 'main', branch: 'main', terminals: [] }).map((m) => m.worktree.path),
    ['/home/ubuntu/leadgen']
  )
  assert.deepEqual(matchServerWorktrees(worktrees, repos, { displayName: 'leadgen', branch: 'main', terminals: [] }), [])
})
